#!/usr/bin/env python3
from __future__ import annotations
import argparse,json,signal,sys,threading
from pathlib import Path
from nelc.common import *
from nelc.workspace import Workspace,ACTIONS
from nelc.portable import backup
from receive_workspace import receive_archive

def main(argv=None,stop=None):
    stop=stop or threading.Event()
    parser=argparse.ArgumentParser(description="NELC source reporting, reviewed CSV migration and portable receiving.")
    parser.add_argument("--workspace",default="nelc-workspace")
    sub=parser.add_subparsers(dest="command",required=True)
    init=sub.add_parser("init");init.add_argument("--name",default="NELC service workbench")
    upload=sub.add_parser("upload");upload.add_argument("file")
    sub.add_parser("overview")
    read=sub.add_parser("record");read.add_argument("kind");read.add_argument("id")
    page=sub.add_parser("page");page.add_argument("kind");page.add_argument("--selection",default="{}")
    page.add_argument("--revision",type=int);page.add_argument("--offset",type=int,default=0);page.add_argument("--limit",type=int,default=50)
    request=sub.add_parser("request");request.add_argument("file",help="The exact original five-field operation request JSON.")
    status=sub.add_parser("request-status");status.add_argument("request_id")
    act=sub.add_parser("act");act.add_argument("action",choices=sorted(ACTIONS));act.add_argument("--data",required=True,help="JSON file.")
    act.add_argument("--request-id",required=True);act.add_argument("--expected-revision",required=True,type=int)
    act.add_argument("--actor-id",required=True);act.add_argument("--actor-name",required=True)
    act.add_argument("--save-request",required=True,help="Retain the exact request before dispatch.")
    check=sub.add_parser("verify");check.add_argument("--metadata-only",action="store_true")
    package=sub.add_parser("backup");package.add_argument("--revision",type=int)
    receive=sub.add_parser("receive");receive.add_argument("archive");receive.add_argument("--output",required=True)
    receive.add_argument("--sha256",required=True);receive.add_argument("--maximum-expanded-bytes",type=int,default=4*1024**3)
    export=sub.add_parser("copy-object");export.add_argument("sha256");export.add_argument("--output",required=True)
    args=parser.parse_args(argv);check_stop(stop)
    if args.command=="receive":result=receive_archive(args.archive,args.output,args.sha256,args.maximum_expanded_bytes,signal=stop)
    else:
        workspace=Workspace(args.workspace,create=args.command=="init",name=getattr(args,"name","NELC service workbench"))
        if args.command=="init":result=workspace.metadata()
        elif args.command=="upload":result=workspace.put_file(args.file,signal=stop)
        elif args.command=="overview":result=workspace.overview()
        elif args.command=="record":result=workspace.record(args.kind,args.id)
        elif args.command=="page":result=workspace.page(args.kind,json.loads(args.selection),args.revision,args.offset,args.limit)
        elif args.command=="request":result=workspace.mutate(json.loads(Path(args.file).read_text("utf-8-sig")),stop)
        elif args.command=="request-status":result=workspace.operation(args.request_id)
        elif args.command=="act":
            data=json.loads(Path(args.data).read_text("utf-8-sig"))
            request={"requestId":args.request_id,"expectedRevision":args.expected_revision,"actor":{"id":args.actor_id,"name":args.actor_name},
                     "action":args.action,"data":data}
            path=Path(args.save_request)
            if path.exists():
                require(json.loads(path.read_text("utf-8"))==request,"REQUEST_FILE_CONFLICT","The retained request file contains different original input.")
            else:atomic_bytes(path,(canonical(request)+"\n").encode("utf-8"))
            result=workspace.mutate(request,stop)
        elif args.command=="verify":result=workspace.verify(full=not args.metadata_only,signal=stop)
        elif args.command=="backup":result=backup(workspace,Path(__file__).resolve().parent,args.revision,signal=stop)
        elif args.command=="copy-object":
            with workspace.connect() as db:
                row=db.execute("SELECT * FROM objects WHERE sha256=?",(args.sha256,)).fetchone()
                require(row is not None,"OBJECT_MISSING","The selected object is not retained.")
                path=workspace.object(db,dict(row),stop)
                target=Path(args.output);require(not target.exists(),"OUTPUT_EXISTS","Choose a fresh output file.")
                import shutil
                with path.open("rb") as source,target.open("xb") as output:
                    for chunk in iter(lambda:source.read(1024*1024),b""):
                        check_stop(stop);output.write(chunk)
                require(file_hash(target,stop)==(row["sha256"],row["bytes"]),"OUTPUT_HASH","The received output differs.")
                result={"path":str(target.absolute()),"sha256":row["sha256"],"bytes":row["bytes"]}
    print(json.dumps(result,ensure_ascii=False,indent=2))
    return 0
if __name__=="__main__":
    stop=threading.Event()
    previous={sig:signal.signal(sig,lambda *unused:stop.set()) for sig in (signal.SIGINT,signal.SIGTERM)}
    try:raise SystemExit(main(stop=stop))
    except Problem as error:
        print(json.dumps({"error":error.as_dict()},ensure_ascii=False),file=sys.stderr);raise SystemExit(2)
    except (KeyboardInterrupt,Cancelled):
        print(json.dumps({"error":{"code":"CANCELLED","message":"The original request remains recoverable."}}),file=sys.stderr);raise SystemExit(130)
    finally:
        for sig,handler in previous.items():signal.signal(sig,handler)

