from __future__ import annotations
import hashlib, json, re
from datetime import date
from decimal import Decimal
from .common import *
from .intake import table_in

IDENTIFIER=re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,79}$")
TRANSFORMS=("identity","trim","upper","lower","decimal","date-iso","constant")

def _identifier(value,field):
    require(isinstance(value,str) and IDENTIFIER.fullmatch(value),"IDENTIFIER",f"{field} must be a stable short identifier.")
    return value

def target_signature(definition):
    return digest({"tables":[{"id":m["id"],"table":m["target"]["table"],
                  "columns":[c["name"] for c in m["target"]["columns"]],"key":m["target"]["key"],
                  "allowRollbackDeleteCreated":m["target"].get("allowRollbackDeleteCreated",False)}
                  for m in definition["tables"]],"relationships":definition.get("relationships",[])})

def validate_definition(store,db,definition):
    require(isinstance(definition,dict),"CONTRACT","Supply a complete mapping contract.")
    d=json.loads(canonical(definition))
    text(d.get("name"),"contract name",maximum=300); text(d.get("authority"),"supplied contract or local receiving authority")
    edition=store.get(db,"edition",d.get("editionId"))
    tables=d.get("tables")
    require(isinstance(tables,list) and 1<=len(tables)<=MAX_TABLES,"TABLE_MAPPINGS","Supply 1–20 explicit table mappings.")
    ids=set(); filenames=set()
    for m in tables:
        require(isinstance(m,dict),"TABLE_MAPPING","Each table mapping must be an object.")
        ident=_identifier(m.get("id"),"mapping ID")
        require(ident not in ids,"MAPPING_DUPLICATE","Table mapping IDs must be unique."); ids.add(ident)
        text(m.get("entity"),"entity description",maximum=300)
        source=table_in(edition,m.get("sourceTableId"))
        headers=source["headers"]
        keys=m.get("sourceKey")
        require(isinstance(keys,list) and keys and len(keys)==len(set(keys)),"SOURCE_KEY","Declare distinct source key columns.")
        for k in keys: column(k,headers)
        scope=m.get("scope",[])
        require(isinstance(scope,list),"SCOPE","Source scope must be a list.")
        for s in scope:
            require(isinstance(s,dict) and s.get("op","equals")=="equals","SCOPE_OPERATOR","Use exact equality for each declared source scope.")
            column(s.get("column"),headers); text(s.get("value"),"scope value",nonempty=False)
        target=m.get("target")
        require(isinstance(target,dict),"TARGET_CONTRACT","Supply the agreed target CSV contract.")
        filename=safe_name(target.get("table"))
        require(filename.lower().endswith(".csv") and filename not in filenames,"TARGET_FILENAME","Target CSV filenames must be distinct.")
        filenames.add(filename)
        columns=target.get("columns")
        require(isinstance(columns,list) and columns and len(columns)<=5000,"TARGET_COLUMNS","Declare every target column in order.")
        names=[]
        for c in columns:
            require(isinstance(c,dict),"TARGET_COLUMN","Each target column must be an explicit mapping.")
            name=text(c.get("name"),"target header",maximum=500)
            require(name not in names,"TARGET_DUPLICATE_HEADER","Target headers must be unique."); names.append(name)
            transform=c.get("transform","identity")
            require(transform in TRANSFORMS,"TRANSFORM","Select a supported explicit transform.")
            if transform=="constant":
                text(c.get("constant"),"constant",nonempty=False)
                require(c.get("source") is None,"CONSTANT_SOURCE","A constant cannot also select a source column.")
            else: column(c.get("source"),headers)
            require(c.get("type","text") in ("text","decimal","integer","date"),"FIELD_TYPE","Choose text, decimal, integer or date.")
            require(isinstance(c.get("required",False),bool),"REQUIRED","Required must be boolean.")
        target_keys=target.get("key")
        require(isinstance(target_keys,list) and target_keys and len(target_keys)==len(set(target_keys))
                and all(x in names for x in target_keys),"TARGET_KEY","Declare distinct target key headers from the actual target columns.")
        require(isinstance(target.get("allowRollbackDeleteCreated",False),bool),"ROLLBACK_POLICY","The created-row rollback policy must be explicit.")
        target.setdefault("encoding","utf-8-sig"); target.setdefault("delimiter",",")
        require(target["encoding"] in ("utf-8","utf-8-sig","cp1252") and len(target["delimiter"])==1
                and target["delimiter"] not in "\r\n\x00",'TARGET_DIALECT',"Declare a supported exact target CSV encoding and delimiter.")
    tokens=d.get("sourceTokens",{})
    require(isinstance(tokens,dict) and all(isinstance(k,str) and isinstance(v,dict) for k,v in tokens.items()),
            "SOURCE_TOKENS","Source token declarations must preserve each original string.")
    relations=d.get("relationships",[])
    require(isinstance(relations,list),"RELATIONSHIPS","Relationships must be a list.")
    rel_ids=set(); mapping={m["id"]:m for m in tables}
    for rel in relations:
        _identifier(rel.get("id"),"relationship ID")
        require(rel["id"] not in rel_ids,"RELATIONSHIP_DUPLICATE","Relationship IDs must be distinct."); rel_ids.add(rel["id"])
        require(rel.get("fromTable") in mapping and rel.get("toTable") in mapping,"RELATIONSHIP_TABLE","Select mapped child and parent tables.")
        a=rel.get("fromFields"); b=rel.get("toFields")
        require(isinstance(a,list) and isinstance(b,list) and a and len(a)==len(b) and len(a)==len(set(a)) and len(b)==len(set(b)),
                "RELATIONSHIP_FIELDS","Declare matching, distinct field tuples on both sides.")
        require(all(x in [c["name"] for c in mapping[rel["fromTable"]]["target"]["columns"]] for x in a)
                and all(x in [c["name"] for c in mapping[rel["toTable"]]["target"]["columns"]] for x in b),
                "RELATIONSHIP_FIELDS","Relationship fields must exist in their actual target tables.")
        require(rel.get("cardinality") in ("many-to-one","one-to-one") and isinstance(rel.get("required"),bool),
                "RELATIONSHIP_RULE","Declare the supplied cardinality and required flag.")
        text(rel.get("reason"),"relationship source/basis")
    rules=d.get("rules",[])
    require(isinstance(rules,list),"RULES","Rules must be a list of supplied source/target requirements.")
    rule_ids=set()
    for rule in rules:
        _identifier(rule.get("id"),"rule ID")
        require(rule["id"] not in rule_ids,"RULE_ID","Rule IDs must be distinct.");rule_ids.add(rule["id"])
        require(rule.get("table") in mapping and rule.get("field") in [c["name"] for c in mapping[rule["table"]]["target"]["columns"]],
                "RULE_FIELD","Select an actual target field.")
        require(rule.get("type") in ("not-empty","one-of","numeric-range") and rule.get("severity") in ("error","warning"),
                "RULE_TYPE","Choose an explicit supported rule and severity.")
        text(rule.get("basis"),"rule source/basis")
        if rule["type"]=="one-of":
            require(isinstance(rule.get("values"),list) and all(isinstance(x,str) for x in rule["values"]),"RULE_VALUES","Allowed values must be source strings.")
        if rule["type"]=="numeric-range":
            if rule.get("minimum") is not None: number(rule["minimum"])
            if rule.get("maximum") is not None: number(rule["maximum"])
    d["tables"]=tables;d.setdefault("relationships",[]);d.setdefault("rules",[]);d.setdefault("sourceTokens",{})
    return d

def save_contract(store,db,data,ctx):
    d=validate_definition(store,db,data.get("definition"))
    previous=data.get("supersedes")
    if previous:
        old=store.get(db,"contract",previous)
        text(data.get("reason"),"contract revision reason")
    return store.put(db,"contract",{"definition":d,"definitionSha256":digest(d),"targetSignature":target_signature(d),
        "supersedes":previous,"reason":data.get("reason","Initial explicit mapping contract."),
        "createdAt":ctx["at"],"actor":ctx["actor"]},ctx["revision"])

def approve_contract(store,db,data,ctx):
    contract=store.get(db,"contract",data.get("contractId"))
    require(data.get("definitionSha256")==contract["definitionSha256"],"CONTRACT_STALE","Review the exact current contract body.")
    require(data.get("sourceReviewed") is True and data.get("authorityConfirmed") is True,
            "CONTRACT_REVIEW","Confirm the exact source edition and supplied or local receiving authority.")
    return store.put(db,"approval",{"contractId":contract["id"],"definitionSha256":contract["definitionSha256"],
        "reason":text(data.get("reason"),"review reason"),"actor":ctx["actor"],"createdAt":ctx["at"],
        "scope":"This local approval binds the selected CSV contract; it is not supplier acceptance."},ctx["revision"])

def approval(store,db,contract):
    matches=[]
    for row in db.execute("SELECT id,data_json FROM records WHERE kind='approval' ORDER BY created_revision,id"):
        value=json.loads(row["data_json"])
        if value["contractId"]==contract["id"] and value["definitionSha256"]==contract["definitionSha256"]:
            matches.append({**value,"id":row["id"]})
    return matches[-1] if matches else None

def map_cell(c,cells,tokens):
    transform=c.get("transform","identity")
    raw=c.get("constant") if transform=="constant" else cells[c["source"]]
    value=raw
    if raw in tokens: value=raw
    elif transform=="trim": value=raw.strip()
    elif transform=="upper": value=raw.upper()
    elif transform=="lower": value=raw.lower()
    elif transform=="decimal" and raw not in tokens: value=format(number(raw),"f")
    elif transform=="date-iso" and raw not in tokens:
        try: value=date.fromisoformat(raw).isoformat()
        except ValueError: raise Problem("DATE_VALUE","An explicit ISO date transform failed.",{"raw":raw})
    if c.get("required") and value=="": raise Problem("REQUIRED_VALUE","A required mapped value is empty.")
    if value not in tokens and value!="":
        typ=c.get("type","text")
        if typ in ("decimal","integer"):
            n=number(value)
            if typ=="integer": require(n==n.to_integral_value(),"INTEGER_VALUE","An integer field has a fractional value.")
        if typ=="date":
            try: date.fromisoformat(value)
            except ValueError: raise Problem("DATE_VALUE","An expected ISO date is invalid.",{"raw":value})
    return value

def assess(store,db,data,ctx):
    contract=store.get(db,"contract",data.get("contractId")); d=contract["definition"]
    edition=store.get(db,"edition",d["editionId"])
    corrections=store.corrections(db,edition["id"])
    correction_ids=sorted(c["id"] for c in corrections.values())
    assessment_id="assessment-"+digest({"contract":contract["id"],"corrections":correction_ids})[:28]
    prior=db.execute("SELECT data_json FROM records WHERE kind='assessment' AND id=?",(assessment_id,)).fetchone()
    if prior:return {**json.loads(prior[0]),"id":assessment_id}
    seq=0; counts={"error":0,"warning":0}; summaries=[]; aggregate=hashlib.sha256()
    def finding(severity,code,mapping,row_ids,details):
        nonlocal seq
        seq+=1; counts[severity]+=1
        db.execute("INSERT INTO findings VALUES(?,?,?,?,?,?,?)",(assessment_id,seq,severity,code,mapping,canonical(row_ids),canonical(details)))
    for mapping in d["tables"]:
        source=table_in(edition,mapping["sourceTableId"]); selected=mapped=0
        headers=[c["name"] for c in mapping["target"]["columns"]]
        for row in db.execute("SELECT * FROM rows WHERE edition_id=? AND table_id=? ORDER BY ordinal",(edition["id"],source["id"])):
