from __future__ import annotations
import hashlib, json, os, tempfile
from .common import *
from .contracts import target_signature
from .intake import table_in
from .releases import zip_objects

def snapshot_digest(signature, iterator):
    h=hashlib.sha256();h.update(canonical({"targetSignature":signature}).encode("utf-8"));h.update(b"\n")
    for mapping_id,target_key,target_id,version,cells in iterator:
        h.update(canonical([mapping_id,target_key,target_id,version,cells]).encode("utf-8"));h.update(b"\n")
    return h.hexdigest()

def return_snapshot(db,return_id,signature):
    iterator=((r["mapping_id"],r["target_key"],r["target_id"],r["version"],json.loads(r["cells_json"]))
              for r in db.execute("SELECT * FROM target_rows WHERE return_id=? ORDER BY mapping_id,target_key,row_id",(return_id,)))
    return snapshot_digest(signature,iterator)

def import_return(store,db,data,ctx):
    contract=store.get(db,"contract",data.get("contractId"));edition=store.get(db,"edition",data.get("editionId"))
    selections=data.get("tables")
    require(isinstance(selections,list) and selections,"RETURN_TABLES","Map the actual returned CSV tables.")
    mappings={m["id"]:m for m in contract["definition"]["tables"]}
    require(len(selections)==len(mappings) and {x.get("mappingId") for x in selections}==set(mappings),
            "RETURN_TABLES","Bind every agreed target table once.")
    basis=text(data.get("basis"),"returned target identity and source basis")
    require(data.get("kind") in ("supplier-export","owned-local-export"),"RETURN_KIND","Identify an actual supplier export or the owned local receiving example.")
    complete=data.get("completeSnapshot")
    require(isinstance(complete,bool),"RETURN_COVERAGE","State whether the selected target export is complete for the agreed scope.")
    if complete:text(data.get("coverageNote"),"complete export scope evidence")
    return_id="target-return-"+digest({"contract":contract["id"],"edition":edition["id"],"tables":selections,"basis":basis,
                                      "kind":data["kind"],"complete":complete,"coverage":data.get("coverageNote")})[:28]
    prior=db.execute("SELECT data_json FROM records WHERE kind='target-return' AND id=?",(return_id,)).fetchone()
    if prior:return {**json.loads(prior[0]),"id":return_id}
    errors=[]; counts={}; total=0
    for selection in selections:
        check_stop(ctx["signal"]);mid=selection["mappingId"];m=mappings[mid];table=table_in(edition,selection.get("tableId"))
        headers=[c["name"] for c in m["target"]["columns"]];fields=selection.get("fields")
        require(isinstance(fields,dict) and set(fields)==set(headers),"RETURN_FIELDS","Map every agreed target field to its actual returned column.")
        for h,i in fields.items():column(i,table["headers"])
        identity=selection.get("identityColumn");version=selection.get("versionColumn");disposition=selection.get("dispositionColumn")
        for value in (identity,version,disposition):
            if value is not None:column(value,table["headers"])
        labels=selection.get("dispositions",{})
        require(isinstance(labels,dict) and set(labels)<= {"accepted","rejected","pending","unknown"}
                and all(isinstance(v,list) and all(isinstance(x,str) for x in v) for v in labels.values()),
                "RETURN_DISPOSITIONS","Map the supplier's actual per-row disposition strings explicitly.")
        reverse={}
        for state,values in labels.items():
            for value in values:
                require(value not in reverse,"RETURN_DISPOSITION_COLLISION","A returned disposition cannot mean two states.");reverse[value]=state
        n=0
        for row in db.execute("SELECT * FROM rows WHERE edition_id=? AND table_id=? ORDER BY ordinal",(edition["id"],table["id"])):
            check_stop(ctx["signal"]);cells=json.loads(row["cells_json"])
            if len(cells)!=len(table["headers"]):
                errors.append({"code":"RETURN_ROW_WIDTH","mappingId":mid,"rowId":row["row_id"]});continue
            output=[cells[fields[h]] for h in headers];values=[output[headers.index(k)] for k in m["target"]["key"]]
            if any(v=="" for v in values):
                errors.append({"code":"RETURN_KEY_EMPTY","mappingId":mid,"rowId":row["row_id"]});continue
            tid=cells[identity] if identity is not None else None;ver=cells[version] if version is not None else None
            if identity is not None and tid=="":
                errors.append({"code":"RETURN_ID_EMPTY","mappingId":mid,"rowId":row["row_id"]});continue
            if version is not None and ver=="":
                errors.append({"code":"RETURN_VERSION_EMPTY","mappingId":mid,"rowId":row["row_id"]});continue
            state=reverse.get(cells[disposition],"unknown") if disposition is not None else "observed"
            proof=digest({"mappingId":mid,"key":values,"targetId":tid,"version":ver,"values":output})
            db.execute("INSERT INTO target_rows VALUES(?,?,?,?,?,?,?,?,?)",(return_id,mid,row["row_id"],key(values),tid,ver,canonical(output),state,proof))
            n+=1;counts[state]=counts.get(state,0)+1
        for group in db.execute("SELECT target_key,count(*) AS n FROM target_rows WHERE return_id=? AND mapping_id=? GROUP BY target_key HAVING count(*)>1",(return_id,mid)):
            errors.append({"code":"RETURN_KEY_COLLISION","mappingId":mid,"key":json.loads(group["target_key"]),"count":group["n"]})
        if identity is not None:
            for group in db.execute("SELECT target_id,count(*) AS n FROM target_rows WHERE return_id=? AND mapping_id=? GROUP BY target_id HAVING count(*)>1",(return_id,mid)):
                errors.append({"code":"RETURN_ID_COLLISION","mappingId":mid,"targetId":group["target_id"],"count":group["n"]})
        total+=n
    details=store.put_bytes(canonical(errors).encode("utf-8"),"target-return-findings.json",db,ctx["signal"])
    value={"schema":"nelc.target-return/v1","contractId":contract["id"],"editionId":edition["id"],"targetSignature":contract["targetSignature"],
        "tables":selections,"kind":data["kind"],"basis":basis,"completeSnapshot":complete,"coverageNote":data.get("coverageNote",""),
        "rows":total,"dispositions":counts,"findingCount":len(errors),"findings":details,"ready":not errors,
        "snapshotSha256":return_snapshot(db,return_id,contract["targetSignature"]),"createdAt":ctx["at"],"actor":ctx["actor"],
        "acceptance":"Only mapped per-row dispositions count as returned acceptance. An unmapped or bulk acknowledgement does not accept individual rows."}
    db.execute("INSERT INTO records VALUES(?,?,?,?)",("target-return",return_id,canonical(value),ctx["revision"]))
    return {**value,"id":return_id}

def accept_baseline(store,db,data,ctx):
    r=store.get(db,"target-return",data.get("returnId"))
    require(r["ready"] and r["completeSnapshot"],"BASELINE_INCOMPLETE","A baseline needs a complete, unambiguous export for the agreed scope.")
    require(data.get("snapshotSha256")==r["snapshotSha256"],"BASELINE_STALE","Review the exact target snapshot before accepting it.")
    return store.put(db,"baseline",{"returnId":r["id"],"snapshotSha256":r["snapshotSha256"],"targetSignature":r["targetSignature"],
        "reason":text(data.get("reason"),"baseline review reason"),"createdAt":ctx["at"],"actor":ctx["actor"]},ctx["revision"])

def _target(row):
    if row is None:return None
    return {"rowId":row["row_id"],"targetId":row["target_id"],"version":row["version"],
            "values":json.loads(row["cells_json"]),"disposition":row["disposition"],"sha256":row["sha256"]}

def compare_target(store,db,data,ctx):
    release=store.get(db,"release",data.get("releaseId"));fresh=store.get(db,"target-return",data.get("currentReturnId"))
    require(fresh["ready"] and fresh["completeSnapshot"],"TARGET_NOT_COMPLETE","Use a complete, unambiguous fresh target export.")
    require(release["targetSignature"]==fresh["targetSignature"],"TARGET_CONTRACT_CHANGED","The target contract changed; review a new baseline.")
    baseline=store.get(db,"baseline",data["baselineId"]) if data.get("baselineId") else None
    base=store.get(db,"target-return",baseline["returnId"]) if baseline else None
    if base:require(base["targetSignature"]==release["targetSignature"],"BASELINE_CONTRACT","The baseline uses a different target contract.")
    name=text(data.get("name"),"comparison name",maximum=300);reason=text(data.get("reason"),"comparison purpose")
    comparison_id="comparison-"+digest({"release":release["id"],"fresh":fresh["id"],"baseline":baseline["id"] if baseline else None,"name":name,"reason":reason})[:28]
    old=db.execute("SELECT data_json FROM records WHERE kind='comparison' AND id=?",(comparison_id,)).fetchone()
    if old:return {**json.loads(old[0]),"id":comparison_id}
    counts={}
    for table in release["tables"]:
        mid=table["id"];headers=table["headers"]
        # SQL union includes current-only keys. Their absence from the source is always retained.
        query="""SELECT target_key FROM mapped_rows WHERE assessment_id=? AND mapping_id=?
                 UNION SELECT target_key FROM target_rows WHERE return_id=? AND mapping_id=?
                 UNION SELECT target_key FROM target_rows WHERE return_id=? AND mapping_id=? ORDER BY target_key"""
        for key_row in db.execute(query,(release["assessmentId"],mid,fresh["id"],mid,base["id"] if base else "",mid)):
            check_stop(ctx["signal"]);k=key_row[0]
            desired=db.execute("SELECT * FROM mapped_rows WHERE assessment_id=? AND mapping_id=? AND target_key=?",(release["assessmentId"],mid,k)).fetchone()
            current=db.execute("SELECT * FROM target_rows WHERE return_id=? AND mapping_id=? AND target_key=?",(fresh["id"],mid,k)).fetchone()
            previous=db.execute("SELECT * FROM target_rows WHERE return_id=? AND mapping_id=? AND target_key=?",(base["id"] if base else "",mid,k)).fetchone()
            d=json.loads(desired["cells_json"]) if desired else None;c=_target(current);b=_target(previous)
            conflicts=[];changes=[];after=d[:] if d is not None else None
            if d is None:status="KEEP_TARGET";after=c["values"][:] if c else None
            elif c is None:
                status="MISSING_TARGET" if b else "CREATE"
                if b:conflicts.append({"code":"TARGET_REMOVED_SINCE_BASELINE"})
            elif d==c["values"]:status="UNCHANGED";after=c["values"][:]
            elif b is None:
                status="CONFLICT";conflicts.append({"code":"EXISTING_TARGET_WITHOUT_BASELINE"})
            elif b["targetId"]!=c["targetId"]:
                status="CONFLICT";conflicts.append({"code":"TARGET_ID_CHANGED"})
            else:
                after=c["values"][:]
                for i,h in enumerate(headers):
                    if d[i]==b["values"][i]:continue
                    if c["values"][i] in (b["values"][i],d[i]):
                        if d[i]!=c["values"][i]:
                            after[i]=d[i];changes.append({"field":h,"before":c["values"][i],"after":d[i]})
                    else:conflicts.append({"field":h,"baseline":b["values"][i],"desired":d[i],"current":c["values"][i]})
                status="CONFLICT" if conflicts else "UPDATE" if changes else "UNCHANGED"
            if status=="CREATE":changes=[{"field":h,"before":None,"after":d[i]} for i,h in enumerate(headers)]
            rid="change-"+digest({"comparison":comparison_id,"mapping":mid,"key":k})[:28]
            value={"id":rid,"mappingId":mid,"key":json.loads(k),"status":status,"sourceRowId":desired["row_id"] if desired else None,
                   "baseline":b,"current":c,"desired":d,"after":after,"changes":changes,"conflicts":conflicts}
            db.execute("INSERT INTO comparison_rows VALUES(?,?,?,?,?,?)",(comparison_id,rid,mid,k,status,canonical(value)))
            counts[status]=counts.get(status,0)+1
    value={"schema":"nelc.comparison/v1","name":name,"reason":reason,"releaseId":release["id"],"currentReturnId":fresh["id"],
        "baselineId":baseline["id"] if baseline else None,"targetSignature":release["targetSignature"],"snapshotSha256":fresh["snapshotSha256"],
        "counts":counts,"rows":sum(counts.values()),"createdAt":ctx["at"],"actor":ctx["actor"],
        "absencePolicy":"A source-absent target row is retained. Independent target changes are preserved; incompatible changed cells remain conflicts."}
    db.execute("INSERT INTO records VALUES(?,?,?,?)",("comparison",comparison_id,canonical(value),ctx["revision"]))
    return {**value,"id":comparison_id}

def comparison_page(db,id,offset=0,limit=50,status=None):
    integer(offset,"offset");integer(limit,"limit",1,200)
    where="comparison_id=?";params=[id]
    if status:where+=" AND status=?";params.append(status)
    total=db.execute("SELECT count(*) FROM comparison_rows WHERE "+where,params).fetchone()[0]
    rows=db.execute("SELECT data_json FROM comparison_rows WHERE "+where+" ORDER BY mapping_id,target_key LIMIT ? OFFSET ?",params+[limit,offset]).fetchall()
    return {"items":[json.loads(r[0]) for r in rows],"total":total,"offset":offset,"nextOffset":offset+len(rows) if offset+len(rows)<total else None}

def _plan_package(store,db,plan_id,meta,operations,ctx):
    fd,tmp=tempfile.mkstemp(prefix=".plan-",dir=store.root);count=0;counts={}
    try:
        with os.fdopen(fd,"w",encoding="utf-8",newline="\n") as out:
            for op in operations:
                check_stop(ctx["signal"]);count+=1;counts[op["action"]]=counts.get(op["action"],0)+1
                db.execute("INSERT INTO plan_rows VALUES(?,?,?)",(plan_id,op["rowId"],canonical(op)))
                out.write(canonical(op)+"\n")
            out.flush();os.fsync(out.fileno())
        with open(tmp,"rb") as source:ops=store.put_stream(source,"operations.ndjson",MAX_INPUT_BYTES,ctx["signal"],db=db)
    finally:
        try:os.unlink(tmp)
        except FileNotFoundError:pass
    require(count>0,"PLAN_EMPTY","Select at least one eligible change.")
    manifest={"schema":"nelc.delta-plan/v1","planId":plan_id,**meta,"operations":ops,"rows":count,"counts":counts,
              "createdAt":ctx["at"],"actor":ctx["actor"],
              "application":"Prepared change instructions. Only the owned local receiver is directly operated; supplier execution needs actual returned evidence."}
    mf=store.put_bytes(canonical(manifest).encode("utf-8"),"PLAN.json",db,ctx["signal"])
    archive=zip_objects(store,db,[("PLAN.json",mf),("operations.ndjson",ops)],"reviewed-change-plan.zip",ctx["signal"])
    value={**manifest,"schema":"nelc.plan/v1","manifest":mf,"archive":archive}
    db.execute("INSERT INTO records VALUES(?,?,?,?)",("plan",plan_id,canonical(value),ctx["revision"]))
    return {**value,"id":plan_id}

def plan_delta(store,db,data,ctx):
    comparison=store.get(db,"comparison",data.get("comparisonId"));release=store.get(db,"release",comparison["releaseId"])
    reason=text(data.get("reason"),"selected change review")
    selected=data.get("rowIds");all_eligible=data.get("allEligible") is True
    require(all_eligible ^ isinstance(selected,list),"PLAN_SELECTION","Select explicit row IDs or explicitly approve every eligible change.")
    if selected is not None:
        require(selected and len(selected)==len(set(selected)) and all(isinstance(x,str) for x in selected),"PLAN_SELECTION","Select distinct reviewed change IDs.")
    plan_id="plan-"+digest({"comparison":comparison["id"],"selection":"all-eligible" if all_eligible else selected,"reason":reason})[:28]
    prior=db.execute("SELECT data_json FROM records WHERE kind='plan' AND id=?",(plan_id,)).fetchone()
    if prior:return {**json.loads(prior[0]),"id":plan_id}
    selected_set=set(selected or []);seen=set()
    def operations():
        for row in db.execute("SELECT * FROM comparison_rows WHERE comparison_id=? ORDER BY mapping_id,target_key",(comparison["id"],)):
            if all_eligible and row["status"] not in ("CREATE","UPDATE"):continue
            if not all_eligible and row["row_id"] not in selected_set:continue
            value=json.loads(row["data_json"]);seen.add(row["row_id"])
            require(value["status"] in ("CREATE","UPDATE") and not value["conflicts"],"PLAN_CONFLICT","A selected row is not an eligible reviewed change.",value["id"])
            yield {"rowId":value["id"],"mappingId":value["mappingId"],"key":value["key"],"action":value["status"].lower(),
                   "sourceRowId":value["sourceRowId"],"before":value["current"],"after":value["after"],"changes":value["changes"]}
        require(all_eligible or seen==selected_set,"PLAN_SELECTION","A selected comparison row does not exist.")
    meta={"kind":"delta","comparisonId":comparison["id"],"releaseId":release["id"],"targetSignature":comparison["targetSignature"],
          "expectedSnapshotSha256":comparison["snapshotSha256"],"reason":reason,
          "tables":[{k:t[k] for k in ("id","file","headers","key","encoding","delimiter","allowRollbackDeleteCreated")} for t in release["tables"]]}
    return _plan_package(store,db,plan_id,meta,operations(),ctx)

def verify_plan(store,db,data,ctx):
    plan=store.get(db,"plan",data.get("planId"));fresh=store.get(db,"target-return",data.get("returnId"))
    require(fresh["ready"] and fresh["completeSnapshot"] and fresh["targetSignature"]==plan["targetSignature"],
            "VERIFICATION_SOURCE","Supply a complete returned target export for this exact contract.")
    observations=[];counts={};all_match=True;all_accepted=True
    for r in db.execute("SELECT data_json FROM plan_rows WHERE plan_id=? ORDER BY row_id",(plan["id"],)):
        check_stop(ctx["signal"]);op=json.loads(r[0]);k=key(op["key"])
        row=db.execute("SELECT * FROM target_rows WHERE return_id=? AND mapping_id=? AND target_key=?",(fresh["id"],op["mappingId"],k)).fetchone()
        current=_target(row);expected_id=op["before"]["targetId"] if op["before"] else None
        if op["action"]=="delete":matched=current is None
        else:matched=current is not None and current["values"]==op["after"] and (op["action"]=="create" or current["targetId"]==expected_id)
        accepted=matched and (current is None or current["disposition"]=="accepted")
        all_match=all_match and matched;all_accepted=all_accepted and accepted
        state="verified" if matched else "not-matched";counts[state]=counts.get(state,0)+1
        observations.append({"rowId":op["rowId"],"mappingId":op["mappingId"],"key":op["key"],"action":op["action"],
                             "matched":matched,"rowAccepted":accepted,"returned":current})
    artifact=store.put_bytes(canonical(observations).encode("utf-8"),"change-return-verification.json",db,ctx["signal"])
    return store.put(db,"verification",{"planId":plan["id"],"returnId":fresh["id"],"snapshotSha256":fresh["snapshotSha256"],
        "targetSignature":plan["targetSignature"],"allFieldsMatched":all_match,"allRowsAccepted":all_accepted,
        "counts":counts,"details":artifact,"reason":text(data.get("reason"),"returned evidence review"),
        "createdAt":ctx["at"],"actor":ctx["actor"]},ctx["revision"])

def plan_rollback(store,db,data,ctx):
    verification=store.get(db,"verification",data.get("verificationId"))
    require(verification["allFieldsMatched"],"ROLLBACK_UNVERIFIED","Retain the actual matched post-change return before preparing rollback.")
    original=store.get(db,"plan",verification["planId"])
    require(original["kind"]=="delta","ROLLBACK_KIND","Select the original delta, not a previous rollback.")
    fresh=store.get(db,"target-return",data.get("currentReturnId"))
    require(fresh["ready"] and fresh["completeSnapshot"] and fresh["targetSignature"]==original["targetSignature"],
            "ROLLBACK_SOURCE","Use a fresh complete export for the same target contract.")
    reason=text(data.get("reason"),"rollback review")
    observed=json.loads(store.object(db,verification["details"],ctx["signal"]).read_text("utf-8"))
    by_id={x["rowId"]:x for x in observed};tables={t["id"]:t for t in original["tables"]}
    selected=data.get("rowIds")
    require(isinstance(selected,list) and selected and len(selected)==len(set(selected)),"ROLLBACK_SELECTION","Explicitly select every change to reverse.")
    plan_id="plan-"+digest({"rollback":verification["id"],"fresh":fresh["id"],"rows":selected,"reason":reason})[:28]
    prior=db.execute("SELECT data_json FROM records WHERE kind='plan' AND id=?",(plan_id,)).fetchone()
    if prior:return {**json.loads(prior[0]),"id":plan_id}
    def operations():
        for row_id in selected:
            check_stop(ctx["signal"])
            row=db.execute("SELECT data_json FROM plan_rows WHERE plan_id=? AND row_id=?",(original["id"],row_id)).fetchone()
            require(row is not None,"ROLLBACK_ROW","The selected row is not part of the original delta.")
            op=json.loads(row[0]);post=by_id[row_id]["returned"]
            current=db.execute("SELECT * FROM target_rows WHERE return_id=? AND mapping_id=? AND target_key=?",(fresh["id"],op["mappingId"],key(op["key"]))).fetchone()
            c=_target(current)
            require(c is not None and post is not None and c["targetId"]==post["targetId"] and c["version"]==post["version"] and c["values"]==post["values"],
                    "ROLLBACK_CONFLICT","The actual target changed after the verified delta; review those changes before rollback.",{"rowId":row_id,"actual":c,"verified":post})
            if op["action"]=="create":
                require(tables[op["mappingId"]]["allowRollbackDeleteCreated"] and data.get("confirmDeleteCreated") is True,
                        "ROLLBACK_DELETE_REVIEW","Deleting a row created by this delta requires the explicit agreed policy and reviewed confirmation.")
                action="delete";after=None
            else:action="update";after=op["before"]["values"]
            yield {"rowId":row_id,"mappingId":op["mappingId"],"key":op["key"],"action":action,
                   "sourceRowId":op.get("sourceRowId"),"before":c,"after":after,
                   "changes":[{"field":h,"before":c["values"][i],"after":after[i] if after else None}
                              for i,h in enumerate(tables[op["mappingId"]]["headers"]) if after is None or after[i]!=c["values"][i]]}
    meta={"kind":"rollback","verificationId":verification["id"],"originalPlanId":original["id"],
          "targetSignature":original["targetSignature"],"expectedSnapshotSha256":fresh["snapshotSha256"],"reason":reason,"tables":original["tables"]}
    return _plan_package(store,db,plan_id,meta,operations(),ctx)

