from __future__ import annotations
import contextlib, hashlib, json, os, shutil, sqlite3, stat, tempfile, threading
from pathlib import Path
from .common import *

DDL = """
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS objects(sha256 TEXT PRIMARY KEY,bytes INTEGER NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS records(kind TEXT NOT NULL,id TEXT PRIMARY KEY,data_json TEXT NOT NULL,created_revision INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS record_kind ON records(kind,created_revision,id);
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY,id TEXT UNIQUE NOT NULL,request_id TEXT UNIQUE NOT NULL,request_sha TEXT NOT NULL,request_json TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL,previous_sha TEXT NOT NULL,sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rows(edition_id TEXT NOT NULL,table_id TEXT NOT NULL,ordinal INTEGER NOT NULL,row_id TEXT NOT NULL,cells_json TEXT NOT NULL,width INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(edition_id,table_id,ordinal));
CREATE UNIQUE INDEX IF NOT EXISTS row_identity ON rows(row_id);
CREATE TABLE IF NOT EXISTS mapped_rows(assessment_id TEXT NOT NULL,mapping_id TEXT NOT NULL,row_id TEXT NOT NULL,source_key TEXT NOT NULL,target_key TEXT NOT NULL,cells_json TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(assessment_id,mapping_id,row_id));
CREATE INDEX IF NOT EXISTS mapped_target ON mapped_rows(assessment_id,mapping_id,target_key);
CREATE INDEX IF NOT EXISTS mapped_source ON mapped_rows(assessment_id,mapping_id,source_key);
CREATE TABLE IF NOT EXISTS findings(assessment_id TEXT NOT NULL,seq INTEGER NOT NULL,severity TEXT NOT NULL,code TEXT NOT NULL,mapping_id TEXT,row_ids_json TEXT NOT NULL,details_json TEXT NOT NULL,PRIMARY KEY(assessment_id,seq));
CREATE TABLE IF NOT EXISTS target_rows(return_id TEXT NOT NULL,mapping_id TEXT NOT NULL,row_id TEXT NOT NULL,target_key TEXT NOT NULL,target_id TEXT,version TEXT,cells_json TEXT NOT NULL,disposition TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(return_id,mapping_id,row_id));
CREATE INDEX IF NOT EXISTS target_key ON target_rows(return_id,mapping_id,target_key);
CREATE TABLE IF NOT EXISTS comparison_rows(comparison_id TEXT NOT NULL,row_id TEXT NOT NULL,mapping_id TEXT NOT NULL,target_key TEXT NOT NULL,status TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(comparison_id,row_id));
CREATE TABLE IF NOT EXISTS plan_rows(plan_id TEXT NOT NULL,row_id TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(plan_id,row_id));
CREATE TABLE IF NOT EXISTS local_rows(target_id TEXT NOT NULL,mapping_id TEXT NOT NULL,target_key TEXT NOT NULL,record_id TEXT NOT NULL,version INTEGER NOT NULL,cells_json TEXT NOT NULL,PRIMARY KEY(target_id,mapping_id,target_key));
"""

class Store:
    def __init__(self, root, create=False, name="NELC service workbench"):
        self.root = Path(root).absolute()
        require(not self.root.is_symlink(), "WORKSPACE_PATH", "The workspace cannot be a symlink.")
        self.lock = threading.RLock()
        if create:
            self.root.mkdir(parents=True, exist_ok=True)
            require(not any(self.root.iterdir()), "WORKSPACE_NOT_EMPTY", "Create the workspace in an empty directory.")
            (self.root/"objects").mkdir(); (self.root/"exports").mkdir(); (self.root/"tasks").mkdir()
            with self.connect() as db:
                db.executescript(DDL)
                import uuid
                values = {"schema":SCHEMA,"id":str(uuid.uuid4()),"name":name,"revision":"0","created_at":now()}
                db.executemany("INSERT INTO meta VALUES(?,?)", values.items())
        require((self.root/"workspace.sqlite").is_file(), "WORKSPACE_MISSING", "Open an existing workspace or create an empty one.")
        with self.connect() as db:
            require(self.meta(db)["schema"] == SCHEMA, "WORKSPACE_SCHEMA", "This workspace version is not supported.")
    def connect(self):
        db = sqlite3.connect(self.root/"workspace.sqlite", timeout=30, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys=ON"); db.execute("PRAGMA busy_timeout=30000")
        db.execute("PRAGMA synchronous=FULL")
        return contextlib.closing(db)
    def meta(self, db):
        m = dict(db.execute("SELECT key,value FROM meta").fetchall()); m["revision"]=int(m["revision"]); return m
    def object_path(self, sha):
        require(isinstance(sha,str) and len(sha)==64 and all(c in "0123456789abcdef" for c in sha),
                "OBJECT_ID", "Select an original object by its full SHA256.")
        path = self.root/"objects"/sha[:2]/sha
        require(not path.is_symlink() and not path.parent.is_symlink(), "OBJECT_PATH", "The object path is not ordinary.")
        return path
    def put_stream(self, stream, name, limit=MAX_INPUT_BYTES, signal=None, db=None):
        safe_name(name)
        root=self.root/"objects"; root.mkdir(exist_ok=True)
        fd,tmp=tempfile.mkstemp(prefix=".incoming-",dir=root)
        h,count=hashlib.sha256(),0
        try:
            with os.fdopen(fd,"wb") as target:
                while True:
                    check_stop(signal); chunk=stream.read(1024*1024)
                    if not chunk: break
                    count+=len(chunk)
                    require(count<=limit,"INPUT_LIMIT","The input exceeds the declared intake size.")
                    h.update(chunk); target.write(chunk)
                target.flush(); os.fsync(target.fileno())
            sha=h.hexdigest(); path=self.object_path(sha); path.parent.mkdir(exist_ok=True)
            if path.exists():
                require(file_hash(path,signal)==(sha,count),"OBJECT_CHANGED","A retained object differs from its identity.")
            else:
                os.chmod(tmp,0o600)
                try: os.link(tmp,path)
                except FileExistsError:
                    require(file_hash(path,signal)==(sha,count),"OBJECT_CHANGED","A retained object differs from its identity.")
                fd2=os.open(path.parent,os.O_RDONLY)
                try: os.fsync(fd2)
                finally: os.close(fd2)
            if db is None:
                with self.connect() as connection:
                    connection.execute("INSERT OR IGNORE INTO objects VALUES(?,?,?,?)",(sha,count,name,now()))
            else:
                db.execute("INSERT OR IGNORE INTO objects VALUES(?,?,?,?)",(sha,count,name,now()))
            return {"sha256":sha,"bytes":count,"name":name}
        finally:
            try: os.unlink(tmp)
            except FileNotFoundError: pass
    def put_file(self,path,signal=None):
        path=Path(path)
        require(path.is_file() and not path.is_symlink(),"INPUT_FILE","Choose a regular local file.")
        with path.open("rb") as stream: return self.put_stream(stream,path.name,signal=signal)
    def put_bytes(self,body,name,db=None,signal=None):
        # Operations can create immutable objects inside their existing transaction.
        import io
        if db is None: return self.put_stream(io.BytesIO(body),name,signal=signal)
        safe_name(name); sha=hashlib.sha256(body).hexdigest(); path=self.object_path(sha)
        if path.exists(): require(file_hash(path,signal)==(sha,len(body)),"OBJECT_CHANGED","A retained object has changed.")
        else: atomic_bytes(path,body)
        db.execute("INSERT OR IGNORE INTO objects VALUES(?,?,?,?)",(sha,len(body),name,now()))
        return {"sha256":sha,"bytes":len(body),"name":name}
    def object(self,db,ref,signal=None):
        require(isinstance(ref,dict),"OBJECT_REFERENCE","Supply a retained object reference.")
        sha=ref.get("sha256"); path=self.object_path(sha)
        row=db.execute("SELECT * FROM objects WHERE sha256=?",(sha,)).fetchone()
        require(row is not None and path.is_file(),"OBJECT_MISSING","The retained original object is missing.")
        require(ref.get("bytes",row["bytes"])==row["bytes"],"OBJECT_SIZE","The object size does not match.")
        require(file_hash(path,signal)==(sha,row["bytes"]),"OBJECT_CHANGED","The original bytes do not match their hash.")
        return path
    def get(self,db,kind,id):
        row=db.execute("SELECT data_json FROM records WHERE kind=? AND id=?",(kind,id)).fetchone()
        require(row is not None,"RECORD_MISSING",f"The selected {kind} does not exist.",{"id":id})
        return {**json.loads(row["data_json"]),"id":id}
    def put(self,db,kind,value,revision):
        require(kind in KINDS,"RECORD_KIND","Unknown record kind.")
        value={k:v for k,v in value.items() if k not in ("id","schema")}
        value={"schema":"nelc."+kind+"/v1",**value}
        id=result_id(kind,value); encoded=canonical(value)
        existing=db.execute("SELECT data_json FROM records WHERE id=?",(id,)).fetchone()
        require(existing is None or existing[0]==encoded,"RECORD_COLLISION","A retained content identity conflicts.")
        db.execute("INSERT OR IGNORE INTO records VALUES(?,?,?,?)",(kind,id,encoded,revision))
        return {**value,"id":id}
    def list(self,db,kind,offset=0,limit=100):
        integer(offset,"offset"); integer(limit,"limit",1,500)
        rows=db.execute("SELECT id,data_json FROM records WHERE kind=? ORDER BY created_revision DESC,id LIMIT ? OFFSET ?",(kind,limit,offset)).fetchall()
        total=db.execute("SELECT count(*) FROM records WHERE kind=?",(kind,)).fetchone()[0]
        return {"items":[{**json.loads(r["data_json"]),"id":r["id"]} for r in rows],"total":total,
                "offset":offset,"nextOffset":offset+len(rows) if offset+len(rows)<total else None}
    def corrections(self,db,edition_id,table_id=None):
        found={}
        for row in db.execute("SELECT id,data_json FROM records WHERE kind='correction' ORDER BY created_revision,id"):
            x={**json.loads(row["data_json"]),"id":row["id"]}
            if x["editionId"]==edition_id and (table_id is None or x["tableId"]==table_id):
                found[(x["tableId"],x["rowId"],x["column"])]=x
        return found
    def effective_cells(self,row,corrections):
        cells=json.loads(row["cells_json"])
        for index in range(len(cells)):
            c=corrections.get((row["table_id"],row["row_id"],index))
            if c is not None: cells[index]=c["to"]
        return cells
    def operation(self,request_id):
        with self.connect() as db:
            row=db.execute("SELECT result_json FROM events WHERE request_id=?",(request_id,)).fetchone()
            return json.loads(row[0]) if row else None
    def audit(self,db,signal=None):
        prior="0"*64; expected=1
        for row in db.execute("SELECT * FROM events ORDER BY seq"):
            check_stop(signal)
            require(row["seq"]==expected and row["previous_sha"]==prior,"HISTORY_CHAIN","The retained history is incomplete.")
            payload={"seq":row["seq"],"id":row["id"],"requestSha256":row["request_sha"],
                     "request":json.loads(row["request_json"]),"result":json.loads(row["result_json"]),
                     "createdAt":row["created_at"],"previousSha256":prior}
            require(digest(payload)==row["sha256"] and digest(payload["request"])==row["request_sha"],
                    "HISTORY_HASH","A retained original operation differs from its hash.")
            prior=row["sha256"]; expected+=1
        require(self.meta(db)["revision"]==expected-1,"HISTORY_REVISION","The revision differs from the complete history.")
        return {"operations":expected-1,"headSha256":prior}

