const renderers={ndtms:ndtmsView,overview:overviewView,sources:sourcesView,contracts:contractsView,findings:findingsView,reports:reportsView,releases:releasesView,returns:returnsView,changes:changesView,recovery:recoveryView,local:localView,delivery:deliveryView,history:historyView};
async function render(){const generation=++state.generation;const route=location.hash.slice(1).split("?")[0]||"overview";state.view=renderers[route]?route:"overview";document.title=(views.find(x=>x[0]===state.view)?.[1]||"Workspace")+" · Service data";
 $("#navigation").innerHTML=views.map(([id,label],i)=>'<a class="nav-link'+(id===state.view?" active":"")+'" href="#'+id+'"'+(id===state.view?' aria-current="page"':"")+'><span class="nav-index">'+String(i).padStart(2,"0")+'</span><span>'+label+"</span></a>").join("");
 $("#breadcrumb").textContent="Service data / "+views.find(x=>x[0]===state.view)[1];$(".shell").classList.remove("menu-open");$("#main").setAttribute("aria-busy","true");
