st{font-family:var(--mono);font-size:10px;line-height:1.6}.status-line{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.error-detail{font-family:var(--mono);font-size:10px}.truncate{display:block;max-width:280px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.login{max-width:620px;margin:9vh auto}.separator{height:1px;background:var(--line);margin:20px 0}.progress-track{height:3px;background:#5d5d5d;margin:12px 0 2px;overflow:hidden}.progress-track:after{content:"";display:block;width:35%;height:100%;background:#dbdbdb;animation:move 1.5s ease-in-out infinite}@keyframes move{from{transform:translateX(-100%)}to{transform:translateX(380%)}}@media(prefers-reduced-motion:reduce){.progress-track:after{animation:none;width:100%}}@media(min-width:1500px){main{padding:38px}.topbar{padding:0 38px}}@media(max-width:1100px){.shell{grid-template-columns:190px minmax(0,1fr)}.rail{padding:23px 11px}.brand{font-size:14px;margin-left:5px}.stats{gap:9px}.stat{padding:15px}.stat-value{font-size:25px}.grid.three{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:24px}.flow{grid-template-columns:repeat(2,minmax(0,1fr))}.flow-step:nth-child(2){border-right:0}.flow-step:nth-child(-n+2){border-bottom:1px solid var(--line)}}@media(max-width:790px){.shell{display:block}.rail{position:fixed;z-index:20;width:226px;transform:translateX(-100%);transition:transform .15s}.shell.menu-open .rail{transform:none;box-shadow:8px 0 30px #0005}.topbar{padding:0 16px;height:60px}.topbar>.icon-button{display:block}.topbar #breadcrumb{display:none}.topbar-right{gap:5px;margin-left:auto}.topbar .mono{font-size:9px}main{padding:22px 16px}.page-header{display:block}.page-actions{margin-top:15px}.page-header h1{font-size:25px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.grid,.grid.three{grid-template-columns:1fr}.form-grid.three{grid-template-columns:1fr}.footer{padding:17px 16px;display:block}.footer span{display:block;margin:3px 0}.notice{margin:12px 16px 0}.record-grid{grid-template-columns:1fr;gap:3px}.record-grid dd{margin-bottom:9px}.panel-body{padding:16px}.panel-header{padding:15px}.toolbar label{min-width:130px}.table-wrap{max-height:510px}.task-tray{right:15px;bottom:15px}.flow-step{padding:15px}.flow-step p{min-height:75px}.chart-row{grid-template-columns:76px minmax(0,1fr) 56px;gap:7px}}@media(max-width:440px){.form-grid{grid-template-columns:1fr;gap:0}.stat-value{font-size:24px}.topbar-right #revision{display:none}.topbar-right .button{font-size:10px;padding:7px}.page-header h1{font-size:23px}.panel-header{align-items:flex-start}.flow{grid-template-columns:1fr}.flow-step{border-right:0;border-bottom:1px solid var(--line)}.flow-step p{min-height:0}.flow-step:last-child{border:0}.check-grid{grid-template-columns:1fr}.page-header p{font-size:12px}.actions .button{flex-grow:1}}

/* Explicit neutral source-operator colour pairs and readable controls. */
body,.main-shell{background:var(--bg);color:var(--ink)}.panel,.panel-body,dialog{background:var(--paper);color:var(--ink)}input,select,textarea{background:#fff;color:#1c1c1c}button:disabled{opacity:1;color:#666;background:#e7e7e7;border-color:#bdbdbd;cursor:not-allowed}.button.primary:disabled{background:#dedede;color:#626262}.nav-link.active small{color:#414141}#ndtms-draft-status{overflow-wrap:anywhere}#ndtms-recovery-controls[hidden]{display:none}.table-wrap pre{max-width:48rem;white-space:pre-wrap;overflow-wrap:anywhere}.table-wrap code{overflow-wrap:anywhere}@media(max-width:600px){.form-grid{grid-template-columns:minmax(0,1fr)}.actions>.button{min-height:40px}.page-header h1{font-size:25px}}
